## Файл 1. `ReadingHistoryCSV.swift` — формирование таблицы

Его место в пакете с логикой приложения. Он использует только Foundation, без SwiftUI.

```swift
import Foundation

/// Собирает CSV с историей чтения, который корректно открывается в Excel и Numbers.
public struct ReadingHistoryCSV: Sendable {

    /// Одна строка таблицы — снимок сессии чтения.
    public struct Row: Sendable, Equatable {
        public var startedAt: Date
        public var duration: TimeInterval
        public var timeZoneIdentifier: String
        public var bookTitle: String
        public var bookAuthor: String

        public init(
            startedAt: Date,
            duration: TimeInterval,
            timeZoneIdentifier: String,
            bookTitle: String,
            bookAuthor: String
        ) {
            self.startedAt = startedAt
            self.duration = duration
            self.timeZoneIdentifier = timeZoneIdentifier
            self.bookTitle = bookTitle
            self.bookAuthor = bookAuthor
        }
    }

    public enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel берёт разделитель из региональных настроек: где десятичная запятая
        /// (Россия, большая часть Европы), там ожидается точка с запятой.
        public static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    public struct Headers: Sendable {
        public var startedAt = "Начало"
        public var durationMinutes = "Длительность, мин"
        public var bookTitle = "Название"
        public var bookAuthor = "Автор"

        public init() {}
    }

    public var delimiter: Delimiter
    public var headers: Headers

    public init(delimiter: Delimiter = .matching(.current), headers: Headers = Headers()) {
        self.delimiter = delimiter
        self.headers = headers
    }

    /// Содержимое файла: UTF-8 с BOM, иначе Excel показывает кириллицу «кракозябрами».
    public func data(for rows: [Row]) -> Data {
        Data(("\u{FEFF}" + text(for: rows)).utf8)
    }

    /// Текст таблицы без BOM. Строки идут по времени начала, от старых к новым.
    public func text(for rows: [Row]) -> String {
        var lines = [line([
            headers.startedAt,
            headers.durationMinutes,
            headers.bookTitle,
            headers.bookAuthor,
        ])]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            lines.append(line([
                Self.localTimestamp(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                String(Self.wholeMinutes(row.duration)),
                Self.neutralizingFormula(row.bookTitle),
                Self.neutralizingFormula(row.bookAuthor),
            ]))
        }
        // Формат CSV (RFC 4180) требует CRLF в конце каждой строки.
        return lines.map { $0 + "\r\n" }.joined()
    }

    /// Имя файла вида «История чтения 2026-10-28.csv».
    public static func suggestedFileName(exportedAt date: Date, timeZone: TimeZone = .current) -> String {
        let stamp = localTimestamp(date, timeZoneIdentifier: timeZone.identifier).prefix(10)
        return "История чтения \(stamp).csv"
    }

    // MARK: - Детали

    private func line(_ fields: [String]) -> String {
        fields.map(Self.quotedIfNeeded).joined(separator: delimiter.rawValue)
    }

    private static let specialCharacters: Set<Unicode.Scalar> = [",", ";", "\"", "\n", "\r"]

    /// Поле с запятой, точкой с запятой, кавычкой или переносом строки берётся в кавычки,
    /// а кавычки внутри удваиваются: `Книга "X"` → `"Книга ""X"""`.
    static func quotedIfNeeded(_ field: String) -> String {
        guard field.unicodeScalars.contains(where: specialCharacters.contains) else { return field }
        return "\"" + field.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// Текст, начинающийся с = + - @, Excel принимает за формулу.
    /// Апостроф в начале заставляет его считать ячейку обычным текстом.
    static func neutralizingFormula(_ text: String) -> String {
        guard let first = text.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) else {
            return text
        }
        return "'" + text
    }

    /// Время по часам того места, где шла сессия, в формате «2026-10-28 21:05».
    /// Excel и Numbers распознают этот формат как дату и время.
    static func localTimestamp(_ date: Date, timeZoneIdentifier: String) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(
            format: "%04ld-%02ld-%02ld %02ld:%02ld",
            c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0
        )
    }

    /// Целые минуты с округлением до ближайшей. Испорченные значения превращаются в 0, а не роняют приложение.
    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        let minutes = (duration / 60).rounded()
        return minutes < Double(Int.max) ? Int(minutes) : 0
    }
}
```

