## Файл 1. `ReadingHistoryCSV.swift`: сборка CSV

Этот файл использует только Foundation, без SwiftUI. Поэтому его можно положить в общий пакет логики.

```swift
import Foundation

/// Собирает CSV с историей чтения для Excel и Numbers.
public enum ReadingHistoryCSV {

    /// Одна строка таблицы. Отдельный простой тип, чтобы экспорт не зависел
    /// от того, как хранится ReadingSession, и безопасно передавался между потоками.
    public struct Row: Sendable, Equatable {
        public var startedAt: Date
        public var duration: TimeInterval
        public var timeZoneIdentifier: String
        public var bookTitle: String
        public var bookAuthor: String

        public init(startedAt: Date, duration: TimeInterval, timeZoneIdentifier: String,
                    bookTitle: String, bookAuthor: String) {
            self.startedAt = startedAt
            self.duration = duration
            self.timeZoneIdentifier = timeZoneIdentifier
            self.bookTitle = bookTitle
            self.bookAuthor = bookAuthor
        }
    }

    public enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel делит CSV на колонки по разделителю списков из региональных настроек.
        /// Где десятичный разделитель запятая (Россия, большая часть Европы), это «;».
        public static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    public static let header = ["Начало", "Длительность (мин)", "Книга", "Автор"]

    /// Готовый файл: UTF-8 с BOM, строки разделены CRLF, сессии по времени начала.
    public static func make(rows: [Row],
                            delimiter: Delimiter,
                            fallbackTimeZone: TimeZone = .current) -> Data {
        var formatters: [String: DateFormatter] = [:]

        func startText(_ row: Row) -> String {
            if let formatter = formatters[row.timeZoneIdentifier] {
                return formatter.string(from: row.startedAt)
            }
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.calendar = Calendar(identifier: .gregorian)
            formatter.timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? fallbackTimeZone
            formatter.dateFormat = "yyyy-MM-dd HH:mm"
            formatters[row.timeZoneIdentifier] = formatter
            return formatter.string(from: row.startedAt)
        }

        func line(_ cells: [String]) -> String {
            cells.map { field($0, delimiter) }.joined(separator: delimiter.rawValue)
        }

        var lines = [line(header)]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            lines.append(line([
                startText(row),
                String(minutes(row.duration)),
                plainText(row.bookTitle),
                plainText(row.bookAuthor),
            ]))
        }

        let body = lines.joined(separator: "\r\n") + "\r\n"
        // BOM нужен, чтобы Excel прочитал кириллицу как UTF-8, а не как «кракозябры».
        return Data([0xEF, 0xBB, 0xBF]) + Data(body.utf8)
    }

    /// Целые минуты с обычным округлением; отрицательные и битые значения дают 0.
    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// Текст, который начинается с =, +, -, @, Excel выполнит как формулу.
    /// Апостроф в начале оставляет его обычным текстом.
    static func plainText(_ value: String) -> String {
        guard let first = value.unicodeScalars.first,
              "=+-@\t\r".unicodeScalars.contains(first) else { return value }
        return "'" + value
    }

    /// Правило RFC 4180: поле с разделителем, кавычкой или переносом строки
    /// берётся в кавычки, а кавычки внутри удваиваются.
    /// Проверка идёт по unicodeScalars: в Swift пара "\r\n" считается одним
    /// символом, и проверка по Character её пропускает.
    static func field(_ value: String, _ delimiter: Delimiter) -> String {
        let special: Set<Unicode.Scalar> = ["\"", "\n", "\r", delimiter.rawValue.unicodeScalars.first!]
        guard value.unicodeScalars.contains(where: special.contains) else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }
}
```

